package com.bank.wellness;

import java.util.*;
import java.util.logging.*;

public class WellnessRosterDemo {
    private static final Logger log = Logger.getLogger("Wellness");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = new ArrayList<>(List.of(
            new Employee(1L, "Rajesh", 30),
            new Employee(2L, "Priya", 28),
            new Employee(3L, "Amit", 30),
            new Employee(4L, "Sneha", 28),
            new Employee(5L, "Vikram", 35)
        ));
        WellnessRosterService service = new WellnessRosterService();
        List<Employee> sorted = service.sortByAgeThenName(staff);
        log.info("Wellness roster (age asc, then name A-Z):");
        sorted.forEach(e -> log.info(() ->
            String.format("  age %2d | %s", e.getAge(), e.getName())));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final int age;
        Employee(Long id, String name, int age) { this.id = id;
        this.name = name
        this.age = age; }
    String getName() { return name; }
    int getAge() { return age; }
}

// ─── Would be in service/WellnessRosterService.java ───
class WellnessRosterService {
    // Primary: age ascending (int key, no boxing). Secondary: name A-Z.
    List<Employee> sortByAgeThenName(List<Employee> employees) {
        return employees.stream()
            .sorted(Comparator.comparingInt(Employee::getAge)
                .thenComparing(Employee::getName))
            .toList();
    }
}
